def make_question(index,row):
 tag,prompt,options,answer,reason=row
 # 讓答案位置分布為 A2/B3/C3/D2；只調整位置，不改動選項語義。
 target_letters=["A","B","C","D","B","C","D","A","C","B"]
 target=target_letters[index-1]
 distractors=[t for t in options if t != answer]
 ordered=[]; di=0
 for letter in ["A","B","C","D"]:
  if letter == target: ordered.append(answer)
  else: ordered.append(distractors[di]); di += 1
 opts=[{"id":chr(65+i),"text":t} for i,t in enumerate(ordered)]; aid=target
 refs=[{"url":u,"title":f"{t}；僅研究公開題型與能力方向，未複製原題。","year":"113-114","subject":"social","locator":l,"observedPattern":"公立學校社會科公開試題常見的資料判讀、比較、地方踏查與證據表達能力，經本題重新設計。","reuseDecision":"pattern-only","status":"recorded","locatorLevel":"paper"} for u,t,l in SOURCES]
 steps=[f"讀題定位：圈出「{tag}」並辨認研究問題、來源、時間、空間或倫理條件。",f"整理證據：分開觀察、比較、推論、資料限制與展演目的；本題核心是「{reason}」。",f"核對正解：選項 {aid}「{answer}」符合主題 K、L 探究與踏查展演的證據推理要求。","排除誘答：檢查是否先決定結論、只選權威或生動材料、忽略樣本與統計口徑，或犧牲安全與隱私。","結論回查：確認主張有證據支持，並標示不確定性、群體差異與下一步研究。"]
 return {"id":f"question-social-content-hist-m-iv-1-{index}","subject":"social","type":"single-choice","prompt":prompt,"options":opts,"knowledgeIds":["kg-social-content-hist-m-iv-1"],"difficulty":"medium","answer":{"value":aid,"explanation":reason},"provenance":{"origin":"original","license":"All rights reserved","sourceUrl":SOURCES[0][0],"sourceLocator":"高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。","authoringNote":"依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫可行問題、檔案脈絡、比較個案、口述沉默、數據圖表、踏查安全、因果推論、展板取捨、地圖空間與結論反思情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"},"reviewStatus":"draft","updatedAt":"2026-09-09","lessonId":"lesson-social-content-hist-m-iv-1","examPatternRefs":refs,"solutionStrategy":"先界定可行問題，再考證檔案與口述來源，接著處理比較、圖表、空間與田野倫理，最後以透明選材和可修正結論完成探究展演。","solutionSteps":steps}

for index,row in enumerate(DATA,1): (OUT/f"question-social-content-hist-m-iv-1-{index}.json").write_text(json.dumps(make_question(index,row),ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
